INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('wdi-milex-gdp','Military expenditure','Military spending as a share of GDP (SIPRI via World Bank).','defence','% of GDP','%','annual',NULL,'multilateral','high','2026-09-04',ARRAY['India''s military burden has fallen steadily as a share of GDP since 2001 even as absolute spending rose — the economy grew faster than the budget.','World Bank indicator MS.MIL.XPND.GD.ZS. History is restated by the World Bank as national accounts are revised; this series is rewritten in full on every pipeline run rather than appended to.','Compiled by SIPRI and redistributed by the World Bank. SIPRI estimates spending on a consistent cross-country definition that does not match India''s own budget headings, so this will not tie to the Ministry of Defence allocation series.','Peer comparison uses each country''s latest available year (2018, 2024), which are not all the same.']::text[],ARRAY['worldbank-wdi','sipri-milex']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
